function update(dt){clock+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}fireTimer=Math.max(0,fireTimer-dt);dashCd=Math.max(0,dashCd-dt);player.inv=Math.max(0,player.inv-dt);hitFlash=Math.max(0,hitFlash-dt);if(reloadTimer>0){reloadTimer-=dt;if(reloadTimer<=0){ammo=12;ui.ammo.textContent=ammo;ui.reload.textContent='';beep(440,.07,'triangle',.02)}}
let mx=(keys.KeyD?1:0)-(keys.KeyA?1:0)+touchMove.x,my=(keys.KeyS?1:0)-(keys.KeyW?1:0)+touchMove.y,m=Math.hypot(mx,my);if(m>1){mx/=m;my/=m}let speed=player.speed*upgrades.speed;player.x+=mx*speed*dt;player.y+=my*speed*dt;player.x=Math.max(28,Math.min(W-28,player.x));player.y=Math.max(46,Math.min(H-46,player.y));
if(mouse.down||touchAim.active){if(fireTimer<=0&&reloadTimer<=0)shoot()}if(dashCd>0){ui.dash.textContent=(dashCd).toFixed(1)+'S';ui.dashBar.style.width=(100*(1-dashCd/(3.1/upgrades.dash)))+'%'}else{ui.dash.textContent='PRONTO';ui.dashBar.style.width='100%'}
for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0||b.x<0||b.y<0||b.x>W||b.y>H){bullets.splice(i,1);continue}let struck=false;for(let e of [...enemies]){if(Math.hypot(e.x-b.x,e.y-b.y)<e.r+b.r){e.hp-=b.damage;e.flash=.09;burst(b.x,b.y,'#b3fff5',3,55);if(e.hp<=0)killEnemy(e);if(b.pierce>0)b.pierce--;else{bullets.splice(i,1);struck=true}break}}if(struck)continue}
if(remaining>0){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();remaining--;spawnTimer=Math.max(.25,1.05-wave*.055)}}else if(enemies.length===0&&!between){if(wave>=9){finish(true);return}openUpgrades()}
for(let e of enemies){e.phase+=dt;e.flash=Math.max(0,e.flash-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;let speed=e.speed*(e.type==='runner'?1.1:1);if(e.type==='spitter'){if(d>260){e.x+=dx/d*speed*dt;e.y+=dy/d*speed*dt}else if(d<180){e.x-=dx/d*speed*.6*dt;e.y-=dy/d*speed*.6*dt}e.attack-=dt;if(e.attack<=0&&d<490){e.attack=2.1;enemyBullets.push({x:e.x,y:e.y,vx:dx/d*185,vy:dy/d*185,r:5,life:3});beep(180,.07,'sine',.012)}}else if(e.type==='boss'){if(d>115){e.x+=dx/d*speed*dt;e.y+=dy/d*speed*dt}e.attack-=dt;if(e.attack<=0){e.attack=1.3;for(let j=0;j<7;j++){let a=Math.atan2(dy,dx)+j*Math.PI*2/7;enemyBullets.push({x:e.x,y:e.y,vx:Math.cos(a)*150,vy:Math.sin(a)*150,r:6,life:4})}}}else{e.x+=dx/d*speed*dt;e.y+=dy/d*speed*dt}if(d<e.r+player.r+2)hitPlayer(e.type==='boss'?24:e.type==='brute'?19:12);}
for(let i=enemyBullets.length-1;i>=0;i--){let b=enemyBullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0||b.x<0||b.y<0||b.x>W||b.y>H){enemyBullets.splice(i,1);continue}if(Math.hypot(player.x-b.x,player.y-b.y)<player.r+b.r){enemyBullets.splice(i,1);hitPlayer(12)}}
for(let i=pickups.length-1;i>=0;i--){let p=pickups[i];p.life-=dt;if(p.life<=0){pickups.splice(i,1);continue}if(Math.hypot(p.x-player.x,p.y-player.y)<24){player.hp=Math.min(100+upgrades.health*20,player.hp+22);pickups.splice(i,1);toast('INTEGRIDADE RESTAURADA');beep(660,.2,'sine',.03)}}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}shake=Math.max(0,shake-dt*20);
ui.hp.textContent=Math.ceil(player.hp)+'%';ui.hpBar.style.width=Math.max(0,100*player.hp/(100+upgrades.health*20))+'%';ui.hpBar.style.background=player.hp<30?'#ff7959':'';ui.kills.textContent=String(kills).padStart(3,'0');ui.score.textContent=String(score).padStart(5,'0');
}
function draw(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);ctx.clearRect(-20,-20,W+40,H+40);let bg=ctx.createRadialGradient(W*.5,H*.48,5,W*.5,H*.48,Math.max(W,H)*.8);bg.addColorStop(0,'#14212a');bg.addColorStop(.7,'#0b121a');bg.addColorStop(1,'#070b11');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
// floor grid and luminous arena markings
ctx.lineWidth=1;for(let x=0;x<W;x+=44){ctx.strokeStyle=x%220===0?'rgba(105,185,185,.085)':'rgba(105,185,185,.035)';ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=44){ctx.strokeStyle=y%220===0?'rgba(105,185,185,.085)':'rgba(105,185,185,.035)';ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
ctx.strokeStyle='rgba(104,242,227,.17)';ctx.lineWidth=1;ctx.strokeRect(25,42,W-50,H-68);ctx.strokeStyle='rgba(104,242,227,.25)';for(let [x,y,sx,sy] of [[25,42,1,1],[W-25,42,-1,1],[25,H-26,1,-1],[W-25,H-26,-1,-1]]){ctx.beginPath();ctx.moveTo(x,y+sy*22);ctx.lineTo(x,y);ctx.lineTo(x+sx*22,y);ctx.stroke()}
// hazard floor rings
for(let i=0;i<4;i++){let x=W*(.19+i*.205),y=H*.49;ctx.beginPath();ctx.arc(x,y,19,0,Math.PI*2);ctx.strokeStyle='rgba(104,242,227,.065)';ctx.stroke();ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fillStyle='rgba(104,242,227,.15)';ctx.fill()}
for(let o of obstacles){ctx.fillStyle='#111d25';ctx.fillRect(o.x-o.w/2,o.y-o.h/2,o.w,o.h);ctx.strokeStyle='rgba(123,170,174,.22)';ctx.lineWidth=1;ctx.strokeRect(o.x-o.w/2,o.y-o.h/2,o.w,o.h);ctx.fillStyle='rgba(104,242,227,.16)';ctx.fillRect(o.x-o.w/2+5,o.y-o.h/2+5,Math.max(3,o.w-10),2);for(let x=o.x-o.w/2+8;x<o.x+o.w/2-5;x+=12){ctx.fillStyle='rgba(164,205,202,.13)';ctx.fillRect(x,o.y-o.h/2+10,4,3)}ctx.fillStyle='rgba(0,0,0,.25)';ctx.fillRect(o.x-o.w/2,o.y+o.h/2,o.w,5)}
for(let p of pickups){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(clock*2);ctx.shadowBlur=14;ctx.shadowColor='#69ffe3';ctx.strokeStyle='#7dffed';ctx.lineWidth=2;ctx.strokeRect(-7,-7,14,14);ctx.beginPath();ctx.moveTo(-4,0);ctx.lineTo(4,0);ctx.moveTo(0,-4);ctx.lineTo(0,4);ctx.stroke();ctx.restore()}
for(let b of bullets){ctx.strokeStyle='#83fff1';ctx.lineWidth=3;ctx.shadowBlur=10;ctx.shadowColor='#6ffff0';ctx.beginPath();ctx.moveTo(b.x-b.vx*.023,b.y-b.vy*.023);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.shadowBlur=0}for(let b of enemyBullets){ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fillStyle='#ff765f';ctx.shadowBlur=14;ctx.shadowColor='#ff5a47';ctx.fill();ctx.shadowBlur=0}
for(let e of enemies)drawEnemy(e);
// hero shadow and dash trail
if(player.inv>0){ctx.beginPath();ctx.arc(player.x,player.y,25+Math.random()*4,0,Math.PI*2);ctx.strokeStyle='rgba(107,255,238,.5)';ctx.stroke()}ctx.save();ctx.translate(player.x,player.y);let aim=touchAim.active?Math.atan2(touchAim.y,touchAim.x):Math.atan2(mouse.y-player.y,mouse.x-player.x);ctx.rotate(aim);ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(1,5,16,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1b333c';ctx.beginPath();ctx.ellipse(0,0,14,11,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#7ffff0';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#60e9de';ctx.fillRect(1,-5,19,4);ctx.fillStyle='#c9fff9';ctx.fillRect(15,-4,8,2);ctx.fillStyle='#18313a';ctx.beginPath();ctx.arc(-4,0,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b8fff6';ctx.fillRect(-6,-2,4,2);ctx.restore();
for(let p of particles){ctx.globalAlpha=Math.max(0,p.life/(p.max||.65));ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}ctx.globalAlpha=1;
if(hitFlash>0){ctx.fillStyle=`rgba(255,60,45,${hitFlash*1.1})`;ctx.fillRect(0,0,W,H)}ctx.restore();}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);let pulse=1+Math.sin(e.phase*5)*.045;ctx.scale(pulse,pulse);let color=e.type==='spitter'?'#ffad68':e.type==='brute'?'#d15871':e.type==='boss'?'#fc5b56':e.type==='runner'?'#d85c91':'#c44c68';ctx.shadowBlur=e.type==='boss'?25:13;ctx.shadowColor=color;ctx.fillStyle=e.flash>0?'#fff':color;ctx.beginPath();if(e.type==='boss'){for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.lineTo(Math.cos(a)*e.r,Math.sin(a)*e.r)}ctx.closePath()}else ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffdbcb';ctx.globalAlpha=.6;ctx.lineWidth=1;ctx.stroke();ctx.globalAlpha=1;let a=Math.atan2(player.y-e.y,player.x-e.x);ctx.rotate(a);ctx.fillStyle='#1b1018';ctx.fillRect(2,-4,e.r*.55,8);ctx.fillStyle='#ffe2c8';ctx.fillRect(e.r*.18,-2,4,4);ctx.restore();if(e.hp<e.max){ctx.fillStyle='#301a24';ctx.fillRect(e.x-e.r,e.y-e.r-8,e.r*2,3);ctx.fillStyle=color;ctx.fillRect(e.x-e.r,e.y-e.r-8,e.r*2*Math.max(0,e.hp/e.max),3)}}
function loop(now){if(!playing)return;let dt=Math.min(.033,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(loop)}

