const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:false, args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1200,height:800},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3000/',{waitUntil:'load'});
 await page.locator('#startBtn').click();
 await page.waitForTimeout(600);
 if(await page.locator('#hud').getAttribute('class')!=='active') throw new Error('HUD did not activate');
 if(await page.locator('#wave').textContent()!=='01') throw new Error('Wave did not initialize');
 await page.keyboard.press('Escape');
 if(!await page.locator('#pauseOverlay').isVisible()) throw new Error('Pause overlay did not open');
 await page.locator('#resumeBtn').click();
 if(await page.locator('#pauseOverlay').isVisible()) throw new Error('Pause overlay did not close');
