const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:false,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3000/',{waitUntil:'load'});
 await page.locator('#startBtn').click();
 const display=await page.locator('#mobileControls').evaluate(el=>getComputedStyle(el).display);
 if(display!=='block')throw new Error(`Mobile controls hidden: ${display}`);
 const stick=await page.locator('#aimStick').boundingBox();
 await page.mouse.move(stick.x+stick.width/2,stick.y+stick.height/2);await page.mouse.down();
 await page.mouse.move(stick.x+stick.width/2,stick.y+stick.height/2-35,{steps:4});
 await page.waitForTimeout(500);await page.mouse.up();
 const ammo=Number(await page.locator('#ammo').textContent());
 if(ammo>=12)throw new Error('Aim stick did not trigger shooting');
 await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/latest.jpg',type:'jpeg',quality:68});
 console.log(JSON.stringify({display,ammo,errors}));
 if(errors.length)throw new Error(errors.join('; '));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
